import { RevenueChartSkeleton } from './components/RevenueChartSkeleton'
import { LatestInvoicesSkeleton } from './components/LatestInvoicesSkeleton'
import { CardStatsSkeleton } from './components/CardStatsSkeleton'

async function CardStatsWrapper() {
  const res = await fetch('https://api.example.com/dashboard/stats')
  const data = await res.json()

  return (
    <div className="grid grid-cols-2 gap-4">
      <div className="card">
        <h2>Total Revenue</h2>
        <p>${data.totalRevenue.toLocaleString()}</p>
      </div>
      <div className="card">
        <h2>Total Invoices</h2>
        <p>{data.totalInvoices}</p>
      </div>
    </div>
  )
}

async function RevenueChartWrapper() {
  const res = await fetch('https://api.example.com/dashboard/revenue')
  const revenue = await res.json()

  return (
    <div className="chart">
      <h2>Revenue</h2>
      <ul>
        {revenue.map((item: { month: string; amount: number }) => (
          <li key={item.month}>
            {item.month}: ${item.amount.toLocaleString()}
          </li>
        ))}
      </ul>
    </div>
  )
}

async function LatestInvoicesWrapper() {
  const res = await fetch('https://api.example.com/dashboard/invoices')
  const invoices = await res.json()

  return (
    <div className="invoices">
      <h2>Latest Invoices</h2>
      <ul>
        {invoices.map((invoice: { id: string; name: string; amount: number }) => (
          <li key={invoice.id}>
            {invoice.name} - ${invoice.amount.toLocaleString()}
          </li>
        ))}
      </ul>
    </div>
  )
}

export default function Page() {
  return (
    <main>
      <h1>Dashboard</h1>
      <Suspense fallback={<CardStatsSkeleton />}>
        <CardStatsWrapper />
      </Suspense>
      <Suspense fallback={<RevenueChartSkeleton />}>
        <RevenueChartWrapper />
      </Suspense>
      <Suspense fallback={<LatestInvoicesSkeleton />}>
        <LatestInvoicesWrapper />
      </Suspense>
    </main>
  )
}

